"use client";

import type React from "react";
import { Easing, interpolate } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import { type RolodexFlipElementId, rolodexFlipTimeline } from "./timeline";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

export interface RolodexFlipProps {
  items: string[];
  from?: number;
  interval?: number;
  flipDuration?: number;
  className?: string;
  style?: React.CSSProperties;
  /**
   * Moves, trims or stretches single flips, by the ids in `./timeline`.
   * Frames on the scene timeline.
   */
  timing?: Timing<RolodexFlipElementId>;
}

export function RolodexFlip(props: RolodexFlipProps) {
  const { items, className, style, timing } = props;
  const glide = useGlide();
  const frame = useSceneFrame();
  const { durationInFrames } = useSceneConfig();
  const tl = useTimeline(rolodexFlipTimeline, props, durationInFrames, timing);
  const sizer = items.reduce((a, b) => (b.length > a.length ? b : a), "");
  return (
    <span
      className={className}
      style={{
        position: "relative",
        display: "inline-block",
        perspective: 420,
        verticalAlign: "bottom",
        ...style,
      }}
    >
      <span style={{ visibility: "hidden" }}>{sizer}</span>
      {items.map((item, i) => {
        // Word `i` turns in on flip `i` and out on flip `i + 1`.
        const flipIn = i > 0 ? tl.get(`flip:${i}`) : undefined;
        const flipOut =
          i < items.length - 1 ? tl.get(`flip:${i + 1}`) : undefined;

        const poseAt = (f: number) => {
          let rotate = 0;
          let y = 0;
          let opacity = 1;

          if (flipIn) {
            const inStart = flipIn.start + flipIn.beat("inAt");
            const pIn = interpolate(
              f,
              [inStart, inStart + flipIn.beat("in")],
              [0, 1],
              { ...clampOpts, easing: Easing.out(Easing.cubic) },
            );
            rotate = (1 - pIn) * -85;
            y = (1 - pIn) * 20;
            opacity = pIn;
          }
          if (flipOut) {
            const pOut = interpolate(
              f,
              [flipOut.start, flipOut.start + flipOut.beat("out")],
              [0, 1],
              { ...clampOpts, easing: Easing.in(Easing.cubic) },
            );
            rotate += pOut * 85;
            y -= pOut * 20;
            opacity *= 1 - pOut;
          }
          return { rotate, y, opacity };
        };
        const { rotate, y, opacity } = poseAt(frame);
        // A word lands flat out of its flip, where a fractional baseline
        // would snap to a whole pixel; the mark keeps it off that grid.
        const turnAt = (f: number) => {
          const p = poseAt(f);
          return `${p.rotate} ${p.y}`;
        };
        const here = `${rotate} ${y}`;
        const moving = here !== turnAt(frame - 1) || here !== turnAt(frame + 1);
        if (opacity <= 0.001) return null;

        return (
          <span
            key={`${i}-${item}`}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              whiteSpace: "nowrap",
              opacity,
              transform: `translateY(${y}px) rotateX(${rotate}deg)${glide(moving)}`,
              transformOrigin: "50% 50%",
              backfaceVisibility: "hidden",
            }}
          >
            {item}
          </span>
        );
      })}
    </span>
  );
}

import { defineTimeline } from "@/lib/remocn/timeline";

// When each flip turns the drum from one word to the next. Frames on the
// 30 fps scene timeline. The ids are public: a saved `timing` prop refers to
// them.

export type RolodexFlipElementId = `flip:${number}`;

export interface RolodexFlipTimingProps {
  items?: string[];
  /** Frame the first flip starts on. */
  from?: number;
  /** Frames between one flip and the next. */
  interval?: number;
  /** Frames a word takes to turn out, and the next one to turn in. */
  flipDuration?: number;
}

/** The words the schedule lays out when none are given. */
const DEFAULT_ITEMS = ["button", "dialog", "command", "tabs", "chart-area"];
const FROM = 0;
const INTERVAL = 20;
const FLIP = 10;

// `flip:<i>` turns word `i - 1` out over its `out` beat and word `i` in over
// `in`, starting `inAt` into the flip.
export const rolodexFlipTimeline = defineTimeline<
  RolodexFlipElementId,
  RolodexFlipTimingProps
>(
  ({
    items = DEFAULT_ITEMS,
    from = FROM,
    interval = INTERVAL,
    flipDuration = FLIP,
  }) =>
    items.slice(1).map((item, k) => {
      const i = k + 1;
      return {
        id: `flip:${i}`,
        lane: "Flips",
        label: item,
        start: from + (i - 1) * interval,
        length: flipDuration / 2 + flipDuration,
        follows: i > 1 ? `flip:${i - 1}` : undefined,
        beats: {
          out: flipDuration,
          inAt: flipDuration / 2,
          in: flipDuration,
        },
      };
    }),
);
